begin;

alter table public.lead_costing_materials
  add column if not exists roll_description text,
  add column if not exists roll_area_m2 numeric(14,6) check (roll_area_m2 is null or roll_area_m2 >= 0),
  add column if not exists supplier_cost_per_m2 numeric(14,6) check (supplier_cost_per_m2 is null or supplier_cost_per_m2 >= 0),
  add column if not exists supplier_cost_per_sq_ft numeric(14,6) check (supplier_cost_per_sq_ft is null or supplier_cost_per_sq_ft >= 0),
  add column if not exists is_sheet boolean not null default false,
  add column if not exists is_finishing boolean not null default false;

alter table public.lead_costing_orders
  add column if not exists waste_allowance_per_project numeric(14,2) not null default 0
    check (waste_allowance_per_project >= 0);

update public.lead_costing_materials
set roll_description = coalesce(roll_description,
      case when roll_width_m is not null and roll_length_m is not null
        then roll_width_m::text || '×' || roll_length_m::text || ' m'
      end),
    roll_area_m2 = coalesce(roll_area_m2, roll_width_m * roll_length_m),
    supplier_cost_per_m2 = coalesce(supplier_cost_per_m2, cost_per_m2),
    supplier_cost_per_sq_ft = coalesce(supplier_cost_per_sq_ft, cost_per_m2 / 10.7639104167);

create index if not exists lead_costing_materials_supplier_idx
  on public.lead_costing_materials(organization_id, supplier_source, name);

