cost_per_m2":51.7213,"supplier_cost_per_m2":51.7213,"supplier_cost_per_sq_ft":4.8051,"source_note":"BMI price list, p.3","is_sheet":false,"is_finishing":false},{"supplier_source":"Brand Maximizers Inc. (BMI)","name":"PVC Plastic Roll 0.5mm","product_code":"BMI-PVC-PLASTIC-0.5MM-1220-50M","roll_description":"1.22×50 m","roll_width_m":1.22,"roll_length_m":50,"roll_area_m2":61,"roll_price":4998,"cost_per_m2":81.9344,"supplier_cost_per_m2":81.9344,"supplier_cost_per_sq_ft":7.612,"source_note":"BMI price list, p.3","is_sheet":false,"is_finishing":false}],"services":[{"name":"Tarpaulin / Banner","examples":"Promotional and event banners","materials":"Banner media","basis":"Per sq ft / sq m","note":"Check media compatibility, finishing equipment, and installation requirements"},{"name":"Vinyl Stickers / Decals","examples":"Logo stickers, product decals","materials":"Adhesive vinyl","basis":"Per sq ft / sheet / piece","note":"Check media compatibility, finishing equipment, and installation requirements"},{"name":"Storefront & Window Graphics","examples":"Window promos, glass door graphics","materials":"Adhesive / perforated / frosted vinyl","basis":"Per sq ft / project","note":"Check media compatibility, finishing equipment, and installation requirements"},{"name":"Wall Graphics / Murals","examples":"Office and interior wall graphics","materials":"Compatible wall media","basis":"Per sq ft / project","note":"Check media compatibility, finishing equipment, and installation requirements"},{"name":"Vehicle Graphics / Partial Wraps","examples":"Vehicle logos and partial wraps","materials":"Vehicle-wrap vinyl","basis":"Per sq ft / project","note":"Check media compatibility, finishing equipment, and installation requirements"},{"name":"Roll-up / Event Displays","examples":"Roll-up and trade show displays","materials":"Display media","basis":"Per piece / package","note":"Check media compatibility, finishing equipment, and installation requirements"},{"name":"Poster Printing","examples":"Retail and promotional posters","materials":"Photo paper / poster media","basis":"Per piece / sq ft","note":"Check media compatibility, finishing equipment, and installation requirements"},{"name":"Backlit Lightbox Graphics","examples":"Illuminated sign graphics","materials":"Backlit film / translucent media","basis":"Per sq ft / project","note":"Check media compatibility, finishing equipment, and installation requirements"},{"name":"Canvas / Art Prints","examples":"Decorative art and photo prints","materials":"Polyester/cotton canvas","basis":"Per piece / sq ft","note":"Check media compatibility, finishing equipment, and installation requirements"},{"name":"Floor Graphics","examples":"Floor decals with anti-slip laminate","materials":"Compatible vinyl + floor laminate","basis":"Per sq ft / project","note":"Check media compatibility, finishing equipment, and installation requirements"},{"name":"Rough-Surface Graphics","examples":"Graphics for semi-rough concrete","materials":"WW 100 rough-surface vinyl","basis":"Per sq ft / project","note":"Check media compatibility, finishing equipment, and installation requirements"},{"name":"One-Way Vision","examples":"Perforated window graphics","materials":"OWV001 One Way Vision","basis":"Per sq ft / project","note":"Check media compatibility, finishing equipment, and installation requirements"},{"name":"Frosted Glass Graphics","examples":"Privacy and decorative film","materials":"JT5796 MBF Frosted","basis":"Per sq ft / project","note":"Check media compatibility, finishing equipment, and installation requirements"}],"printerCosts":[{"item":"Magenta ink","unit":"1,000 ml","listedCost":6250,"costPerUnit":6.25,"notes":"As shown"},{"item":"Light Magenta ink","unit":"1,000 ml","listedCost":6250,"costPerUnit":6.25,"notes":"As shown"},{"item":"Light Cyan ink","unit":"1,000 ml","listedCost":6250,"costPerUnit":6.25,"notes":"As shown"},{"item":"Cyan ink","unit":"1,000 ml","listedCost":6250,"costPerUnit":6.25,"notes":"As shown"},{"item":"Yellow ink","unit":"1,000 ml","listedCost":6250,"costPerUnit":6.25,"notes":"As shown"},{"item":"Black ink","unit":"1,000 ml","listedCost":6250,"costPerUnit":6.25,"notes":"As shown"},{"item":"Optimizer","unit":"1,000 ml","listedCost":750,"costPerUnit":0.75,"notes":"As shown"},{"item":"Overcoat","unit":"1,000 ml","listedCost":750,"costPerUnit":0.75,"notes":"As shown"},{"item":"White ink","unit":"1,000 ml","listedCost":6250,"costPerUnit":6.25,"notes":"Verify model is 700W; white ink may not apply to standard 700"},{"item":"Printhead","unit":"Photo shows 2,500 and 8,250","listedCost":8250,"costPerUnit":3.3,"notes":"Unit/lifetime context unclear; verify before using"},{"item":"Maintenance kit","unit":"Photo shows 9,500 / 8,950","listedCost":8950,"costPerUnit":0.94,"notes":"Photo says maintenance kit/roll lasts up to 14,000 ml ink usage; verify"},{"item":"Average total print cost / m²","unit":"Source total","listedCost":null,"costPerUnit":99.19,"notes":"Converted for unit consistency; confirm source scope and approved base rate"},{"item":"Average total print cost / sq ft","unit":"Source total","listedCost":null,"costPerUnit":9.27,"notes":"Converted for unit consistency; confirm source scope and approved base rate"},{"item":"Average total print cost / sq in","unit":"Source total","listedCost":null,"costPerUnit":0.06,"notes":"Converted for unit consistency; confirm source scope and approved base rate"},{"item":"Unit consistency: printer-cost rates are normalized from ₱9.27/sq ft (m² and sq in are mathematically converted). The source photo's ₱99.19/m² and ₱0.06/sq in do not convert exactly to ₱9.27/sq ft, so confirm the approved base rate. Verify exact HP Latex model and printhead/maintenance basis before treating these as confirmed costs.","unit":null,"listedCost":null,"costPerUnit":null,"notes":null}]}$lead_costing_data$;
begin
  update public.lead_costing_services service
  set examples = seed.examples,
      material_guidance = seed.materials,
      pricing_basis = seed.basis,
      notes = seed.note,
      updated_at = now()
  from public.organizations org
  cross join jsonb_to_recordset(v_data->'services') as seed(
    name text, examples text, materials text, basis text, note text
  )
  where service.organization_id = org.id
    and service.name = seed.name;

  insert into public.lead_costing_services (
    organization_id, name, examples, material_guidance, pricing_basis, notes
  )
  select org.id, seed.name, seed.examples, seed.materials, seed.basis, seed.note
  from public.organizations org
  cross join jsonb_to_recordset(v_data->'services') as seed(
    name text, examples text, materials text, basis text, note text
  )
  where not exists (
    select 1
    from public.lead_costing_services existing
    where existing.organization_id = org.id
      and existing.name = seed.name
  );

  insert into public.lead_costing_materials (
    organization_id, supplier_source, name, product_code, roll_description,
    roll_width_m, roll_length_m, roll_area_m2, roll_price, cost_per_m2,
    supplier_cost_per_m2, supplier_cost_per_sq_ft, source_note, is_sheet, is_finishing
  )
  select org.id, seed.supplier_source, seed.name, seed.product_code, seed.roll_description,
         seed.roll_width_m, seed.roll_length_m, seed.roll_area_m2, seed.roll_price,
         seed.cost_per_m2, seed.supplier_cost_per_m2, seed.supplier_cost_per_sq_ft,
         seed.source_note, seed.is_sheet, seed.is_finishing
  from public.organizations org
  cross join jsonb_to_recordset(v_data->'materials') as seed(
    supplier_source text, name text, product_code text, roll_description text,
    roll_width_m numeric, roll_length_m numeric, roll_area_m2 numeric,
    roll_price numeric, cost_per_m2 numeric, supplier_cost_per_m2 numeric,
    supplier_cost_per_sq_ft numeric, source_note text, is_sheet boolean,
    is_finishing boolean
  )
  where not exists (
    select 1
    from public.lead_costing_materials existing
    where existing.organization_id = org.id
      and existing.supplier_source = seed.supplier_source
      and existing.name = seed.name
      and coalesce(existing.product_code, '') = coalesce(seed.product_code, '')
  );

  update public.lead_costing_printer_costs printer
  set unit = seed.unit,
      listed_cost = seed."listedCost",
      cost_per_unit = seed."costPerUnit",
      notes = seed.notes,
      updated_at = now()
  from public.organizations org
  cross join jsonb_to_recordset(v_data->'printerCosts') as seed(
    item text, unit text, "listedCost" numeric, "costPerUnit" numeric, notes text
  )
  where printer.organization_id = org.id
    and printer.item = seed.item;

  insert into public.lead_costing_printer_costs (
    organization_id, item, unit, listed_cost, cost_per_unit, notes
  )
  select org.id, seed.item, seed.unit, seed."listedCost", seed."costPerUnit", seed.notes
  from public.organizations org
  cross join jsonb_to_recordset(v_data->'printerCosts') as seed(
    item text, unit text, "listedCost" numeric, "costPerUnit" numeric, notes text
  )
  where not exists (
    select 1
    from public.lead_costing_printer_costs existing
    where existing.organization_id = org.id
      and existing.item = seed.item
  );
end;
$seed$;

create or replace function public.create_lead_costing_order_from_index(
  p_organization_id uuid,
  p_customer_id uuid,
  p_service_id uuid,
  p_material_id uuid,
  p_order_date date,
  p_customer_name text,
  p_order_description text,
  p_payment_mode text,
  p_amount_paid numeric,
  p_width numeric,
  p_height numeric,
  p_measurement_unit text,
  p_quantity integer,
  p_media_rate numeric,
  p_print_rate numeric,
  p_waste_allowance_per_project numeric,
  p_lamination_type text,
  p_policy_text text
)
returns public.lead_costing_orders
language plpgsql
security invoker
set search_path = public, private
as $function$
declare
  v_material public.lead_costing_materials%rowtype;
  v_inventory public.lead_costing_inventory%rowtype;
  v_row public.lead_costing_orders%rowtype;
  v_unit_factor numeric;
  v_w_m numeric;
  v_h_m numeric;
  v_area_input numeric;
  v_printed_area numeric;
  v_roll_width numeric;
  v_roll_length numeric;
  v_best_length numeric := null;
  v_waste_area numeric := 0;
  v_waste_percent numeric := 0;
  v_cost_allowance numeric := 0;
  v_across numeric;
  v_rows numeric;
  v_candidate_length numeric;
  v_lamination numeric;
  v_media_per_item numeric;
  v_ink_per_item numeric;
  v_direct_per_item numeric;
  v_waste_per_item numeric;
  v_total_cost numeric;
  v_amount_paid numeric;
  v_balance numeric;
  v_payment_status text;
  v_stock_fit_status text;
begin
  if not private.lead_costing_is_operator(p_organization_id) then
    raise exception 'Only a Lead & Costing Coordinator can create costing orders';
  end if;
  if nullif(btrim(coalesce(p_customer_name, '')), '') is null
     or nullif(btrim(coalesce(p_order_description, '')), '') is null then
    raise exception 'Customer name and order description are required';
  end if;
  if p_width is null or p_height is null or p_width <= 0 or p_height <= 0
     or p_quantity is null or p_quantity <= 0 then
    raise exception 'Dimensions and quantity must be positive';
  end if;
  if p_measurement_unit not in ('ft', 'in', 'm') then
    raise exception 'Unsupported measurement unit';
  end if;
  if p_lamination_type not in ('none', 'matte', 'glossy') then
    raise exception 'Unsupported lamination type';
  end if;
  if p_waste_allowance_per_project is null or p_waste_allowance_per_project < 0 then
    raise exception 'Wastage allowance must be zero or greater';
  end if;
  if p_service_id is null or not exists (
    select 1
    from public.lead_costing_services
    where id = p_service_id and organization_id = p_organization_id and is_active
  ) then
    raise exception 'Select an active service before saving the order';
  end if;
  if p_customer_id is not null and not exists (
    select 1
    from public.lead_costing_customers
    where id = p_customer_id and organization_id = p_organization_id
  ) then
    raise exception 'The selected customer does not belong to this organization';
  end if;

  select * into v_material
  from public.lead_costing_materials
  where id = p_material_id and organization_id = p_organization_id and is_active;
  if not found then
    raise exception 'Select an active material before saving the order';
  end if;

  v_unit_factor := case p_measurement_unit when 'ft' then 0.3048 when 'in' then 0.0254 else 1 end;
  v_w_m := p_width * v_unit_factor;
  v_h_m := p_height * v_unit_factor;
  v_area_input := p_width * p_height;
  v_printed_area := v_w_m * v_h_m * p_quantity;
  v_roll_width := v_material.roll_width_m;
  v_roll_length := v_material.roll_length_m;
  v_stock_fit_status := 'Roll dimensions unavailable';

  if v_roll_width is not null and v_roll_length is not null then
    foreach v_candidate_length in array array[v_h_m, v_w_m] loop
      v_across := floor((v_roll_width + 0.000000001) /
        case when v_candidate_length = v_h_m then v_w_m else v_h_m end);
      if v_across >= 1 then
        v_rows := ceil(p_quantity::numeric / v_across);
        if v_best_length is null or (v_rows * v_candidate_length) < v_best_length then
          v_best_length := v_rows * v_candidate_length;
        end if;
      end if;
    end loop;

    if v_best_length is not null then
      v_waste_area := greatest(0, v_roll_width * v_best_length - v_printed_area);
      v_waste_percent := case
        when v_roll_width * v_best_length > 0
        then v_waste_area / (v_roll_width * v_best_length) * 100
        else 0
      end;
      v_cost_allowance := case
        when v_printed_area > 0 then v_waste_area / v_printed_area * 100
        else 0
      end;

      select * into v_inventory
      from public.lead_costing_inventory
      where organization_id = p_organization_id and material_id = p_material_id;
       if not found
          or (v_inventory.full_rolls_on_hand is null and v_inventory.remaining_meters is null) then
        v_stock_fit_status := 'Enter roll count or remaining meters';
      elsif (
        coalesce(v_inventory.full_rolls_on_hand, 0) * v_roll_length
        + coalesce(v_inventory.remaining_meters, 0)
      ) >= v_best_length * 1.1 then
        v_stock_fit_status := 'In stock';
      else
        v_stock_fit_status := 'Insufficient stock';
      end if;
    else
      v_stock_fit_status := 'Job does not fit the selected roll width';
    end if;
  end if;

  v_lamination := case p_lamination_type
    when 'matte' then (v_w_m / 0.0254) * (v_h_m / 0.0254) * 0.008
    when 'glossy' then (v_w_m / 0.0254) * (v_h_m / 0.0254) * 0.0755
    else 0
  end;
  v_media_per_item := v_area_input * greatest(0, coalesce(p_media_rate, 0));
  v_ink_per_item := v_area_input * greatest(0, coalesce(p_print_rate, 0));
  v_direct_per_item := v_media_per_item + v_ink_per_item + v_lamination;
  v_waste_per_item := greatest(0, p_waste_allowance_per_project) / p_quantity;
  v_total_cost := (v_direct_per_item + v_waste_per_item) * p_quantity;
  v_amount_paid := least(greatest(0, coalesce(p_amount_paid, 0)), v_total_cost);
  v_balance := greatest(0, v_total_cost - v_amount_paid);
  v_payment_status := case
    when v_balance <= 0.009 then 'Paid in full'
    when v_amount_paid > 0 then 'Partially paid'
    else 'Unpaid'
  end;

  insert into public.lead_costing_orders (
    organization_id, order_no, customer_id, service_id, material_id, order_date,
    customer_name, order_description, payment_mode, payment_status, amount_paid,
    balance_due, width, height, measurement_unit, quantity, media_rate, ink_rate,
    lamination_type, labor_per_order, other_costs_per_order, target_margin,
    policy_text, waste_allowance_per_project, printed_area_m2, required_length_m,
    waste_percent, cost_allowance_percent, material_cost_per_item,
    ink_cost_per_item, lamination_cost_per_item, direct_cost_per_item,
    waste_cost_per_item, total_production_cost, selling_price_per_item,
    total_quotation, estimated_profit, stock_fit_status, created_by
  ) values (
    p_organization_id,
    'LC-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISS') || '-' ||
      substr(gen_random_uuid()::text, 1, 6),
    p_customer_id, p_service_id, p_material_id, coalesce(p_order_date, current_date),
    btrim(p_customer_name), btrim(p_order_description),
    coalesce(nullif(btrim(p_payment_mode), ''), 'Cash'),
    v_payment_status, v_amount_paid, v_balance, p_width, p_height,
    p_measurement_unit, p_quantity, greatest(0, coalesce(p_media_rate, 0)),
    greatest(0, coalesce(p_print_rate, 0)), p_lamination_type, 0, 0, 0,
    p_policy_text, greatest(0, p_waste_allowance_per_project), v_printed_area,
    coalesce(v_best_length, 0), v_waste_percent, v_cost_allowance,
    v_media_per_item, v_ink_per_item, v_lamination, v_direct_per_item,
    v_waste_per_item, v_total_cost, v_total_cost / p_quantity, v_total_cost,
    0, v_stock_fit_status, (select auth.uid())
  )
  returning * into v_row;

  return v_row;
end;
$function$;

revoke all on function public.create_lead_costing_order_from_index(
  uuid, uuid, uuid, uuid, date, text, text, text, numeric, numeric, numeric,
  text, integer, numeric, numeric, numeric, text, text
) from public, anon, authenticated;
grant execute on function public.create_lead_costing_order_from_index(
  uuid, uuid, uuid, uuid, date, text, text, text, numeric, numeric, numeric,
  text, integer, numeric, numeric, numeric, text, text
) to authenticated;

commit;
